import pyomo.environ as pyo

DATA = {
    "nodes": ["E", "F", "G", "H", "I"],
    "anchor_index": 0,          # arbitrary node whose order is fixed to 1
    "cost": {
        ("E", "F"): 65, ("E", "G"): 10, ("E", "H"): 25, ("E", "I"): 82,
        ("F", "E"): 65, ("F", "G"): 98, ("F", "H"): 42, ("F", "I"): 26,
        ("G", "E"): 10, ("G", "F"): 98, ("G", "H"): 75, ("G", "I"): 72,
        ("H", "E"): 25, ("H", "F"): 42, ("H", "G"): 75, ("H", "I"): 46,
        ("I", "E"): 82, ("I", "F"): 26, ("I", "G"): 72, ("I", "H"): 46,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    nodes = d["nodes"]
    n = len(nodes)
    anchor = d["anchor_index"]
    idx = {name: k for k, name in enumerate(nodes)}

    cost_by_index = {}
    for (a, b), c in d["cost"].items():
        cost_by_index[(idx[a], idx[b])] = c

    arcs = [(i, j) for i in range(n) for j in range(n) if i != j]

    model = pyo.ConcreteModel()
    model.N = pyo.RangeSet(0, n - 1)
    model.A = pyo.Set(initialize=arcs, dimen=2)

    # x[i,j] = 1 if the courier travels directly from i to j
    model.x = pyo.Var(model.A, domain=pyo.Binary)

    # MTZ order variables: anchor fixed to 1, others in [2, n]
    model.u = pyo.Var(model.N, domain=pyo.NonNegativeReals, bounds=(1, n))

    # Objective: minimise total delivery cost of the closed tour
    def obj_rule(m):
        return sum(cost_by_index[(i, j)] * m.x[i, j] for (i, j) in arcs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each location: exactly one outgoing arc
    def out_rule(m, i):
        return sum(m.x[i, j] for j in range(n) if j != i) == 1

    model.out_arc = pyo.Constraint(model.N, rule=out_rule)

    # Each location: exactly one incoming arc
    def in_rule(m, j):
        return sum(m.x[i, j] for i in range(n) if i != j) == 1

    model.in_arc = pyo.Constraint(model.N, rule=in_rule)

    # Anchor order variable
    def anchor_rule(m):
        return m.u[anchor] == 1

    model.anchor_order = pyo.Constraint(rule=anchor_rule)

    # MTZ subtour elimination on arcs not leaving the anchor
    def mtz_rule(m, i, j):
        return m.u[j] >= m.u[i] + 1 - n * (1 - m.x[i, j])

    model.mtz = pyo.Constraint(
        [(i, j) for (i, j) in arcs if i != anchor], rule=mtz_rule
    )

    return model
